implementation

{ TMessageContentBuilder }

class procedure TMessageContentBuilder.AppendImageBlock(
  const AFullPath: string;
  var ABlocks: TArray<TContentBlockParam>);
begin
  {--- Always converts a local image into an Anthropic-compatible block.
       The file is base64-encoded and tagged with its MIME type so the API
       can correctly interpret the binary payload. }
  var Block := TImageBlockParam.New
    .Source(
      TMediaCodec.EncodeBase64(AFullPath),
      TMediaCodec.GetMimeType(AFullPath)
    );

  ABlocks := ABlocks + [Block];
end;

class procedure TMessageContentBuilder.AppendDocumentBlock(
  const AFullPath: string;
  var ABlocks: TArray<TContentBlockParam>);
begin
  {--- Document handling depends on the MIME type detected locally.
       This method acts as the dispatch point between the formats actually
       supported by the Anthropic payload built here. }
  var MimeType := TMediaCodec.GetMimeType(AFullPath);

  if SameText(MimeType, 'application/pdf') then
    begin
      {--- PDFs are sent as base64-encoded binary documents.
           The media type is preserved explicitly so the backend can
           distinguish this payload from plain serialized text. }
      var Block := TDocumentBlockParam.New
        .Source(
          TBase64PDFSource.New
            .Data(TMediaCodec.EncodeBase64(AFullPath))
            .MediaType(MimeType)
        );

      ABlocks := ABlocks + [Block];
      Exit;
    end;

  if SameText(MimeType, 'text/plain') or
     SameText(MimeType, 'application/octet-stream') or
     SameText(MimeType, 'text/html') then  //markdown file
    begin
      {--- Plain text files are injected directly into the document block.
           This avoids unnecessary encoding and allows the model to consume
           the textual content without an extra decoding step. }
      var Block := TDocumentBlockParam.New
        .Source(
          TPlainTextSource.New
            .Data(TFileIOHelper.LoadFromFile(AFullPath))
            .MediaType('text/plain')
        );

      ABlocks := ABlocks + [Block];
    end;
end;

class procedure TMessageContentBuilder.AppendTextBlock(
  const AText: string;
  var ABlocks: TArray<TContentBlockParam>);
begin
  {--- Free-form text is always appended last as the conversational block.
       This makes it possible to aggregate contextual attachments first and
       then add the user's instruction or question. }
  ABlocks := ABlocks + [
    TTextBlockParam.New.Text(AText)
  ];
end;

class function TMessageContentBuilder.BuildContentBlocks(
  const AState: TStateBuffer): TArray<TContentBlockParam>;
begin
  {--- Builds the multimodal user message content from the current UI state.
       The aggregation order is meaningful: images, files, results, and then
       free-form text. }
  Result := [];

  for var Item in AState.Images do
    AppendImageBlock(Item.FullPath, Result);

  for var Item in AState.Files do
    AppendDocumentBlock(Item.FullPath, Result);

  {--- KnowledgeSearch files are intentionally not appended as prompt documents.
       They are expected to be indexed/vectorized and retrieved through the
       knowledge-search pipeline instead of being injected directly here. }
//  for var Item in AState.KnowledgeSearch do
//    AppendDocumentBlock(Item.FullPath, Result);

  AppendTextBlock(AState.Text, Result);
end;

{ TThinkingBuilder }

class function TThinkingBuilder.GetTOutputConfig(
  const AState: TStateBuffer;
  const Effort: string): TOutputConfig;
var
  HasStruturedOutput: Boolean;
  HasEffort: Boolean;
  BudgetCoef: Double;
begin
  var CoreParams := AState.CoreParamsState;
  HasStruturedOutput := CoreParams.StructuredOutput.Enabled;

  var Content := CoreParams.StructuredOutput.Value;

  {--- Builds a TOutputConfig object only when the requested level can be
       translated into a value supported by the SDK. Otherwise nil is returned
       so the caller can decide not to populate the field. }
  var OutputEffort := TStateChecking.MapToOutputEffort(Effort, BudgetCoef);
  HasEffort := not OutputEffort.IsEmpty;

  var IsAdaptive := TStateChecking.AdaptiveThinkingCheck(AState);
  if not IsAdaptive then
    HasEffort := False;

  if HasEffort then
    begin
      if HasStruturedOutput then
        Result := TOutputConfig.New
          .Effort(OutputEffort)
          .Format(CoreParams.StructuredOutput.Value)
      else
        Result := TOutputConfig.New
          .Effort(OutputEffort)
    end
  else
  if HasStruturedOutput then
    Result := TOutputConfig.New
      .Format(CoreParams.StructuredOutput.Value)
  else
    Result := nil;
end;

class function TThinkingBuilder.TryGetOutputConfig(
  const AState: TStateBuffer;
  out Effort: string;
  const ParamProc: TProc): Boolean;
begin
  {--- Exposes the current thinking level while applying the same logical
       guard used elsewhere: if thinking is disabled, the parameterization
       procedure is not executed. }
  Effort := AState.Thinking;
  Result := TStateChecking.HasEffort(Effort);

  if not Result then
    Exit;

  if Assigned(ParamProc) then
    ParamProc();
end;

class function TThinkingBuilder.TryGetThinkingConfigParam(
  const AState: TStateBuffer;
  const Effort: string;
  const ParamProc: TProc): Boolean;
begin
  var StructuredOutput := AState.CoreParamsState.StructuredOutput;
  var HasStructuredOutput :=
    StructuredOutput.Enabled and not StructuredOutput.Value.IsEmpty;

  Result := TStateChecking.HasEffort(Effort) or HasStructuredOutput;

  if not Result then
    Exit;

  if Assigned(ParamProc) then
    ParamProc();
end;

{ TToolsBuilder }

class function TToolsBuilder.TryToBuild(const AState: TStateBuffer;
  const ParamProc: TProc): Boolean;
begin
  {--- Enables tool construction only when the current state explicitly requested
       web search, skills or MCP. This builder acts as an activation guard to avoid
       emitting "tools" parameters when the feature is not in use. }
  Result := AState.WebSearch or
            TStateChecking.HasSkills(AState) or
            TStateChecking.HasMCP(AState);

  if not Result then
    Exit;

  if Assigned(ParamProc) then
    ParamProc();
end;

{ TRequestSettingsBuilder }

class procedure TRequestSettingsBuilder.ApplyMaxTokens(
  const AState: TStateBuffer;
  const ParamProc: TProc<Integer>;
  const ADefaultValue: Integer);
var
  Value: Integer;
begin
  {--- Resolves the final max_tokens value from the business configuration.
       If the setting is not enabled in the state, it falls back to a default
       value provided by the caller to keep the request valid. }
  var CoreParams := AState.CoreParamsState;

  if CoreParams.Settings.MaxToken.Enabled then
    Value := CoreParams.Settings.MaxToken.Value
  else
    Value := ADefaultValue;

  if Assigned(ParamProc) then
    ParamProc(Value);
end;

class function TRequestSettingsBuilder.TryApplySystemPrompt(
  const AState: TStateBuffer;
  const ParamProc: TProc<string>): Boolean;
begin
  {--- The system prompt is sent only when it is explicitly enabled and non-empty.
       The Trim check avoids sending a purely cosmetic "system" field that
       would provide no actionable instruction to the model. }
  var CoreParams := AState.CoreParamsState;

  Result := CoreParams.SystemPrompt.Enabled
    and (Trim(CoreParams.SystemPrompt.Value) <> '');

  if Result and Assigned(ParamProc) then
    ParamProc(CoreParams.SystemPrompt.Value);
end;

class function TRequestSettingsBuilder.TryApplyTemperature(
  const AState: TStateBuffer;
  const ParamProc: TProc<Double>): Boolean;
begin
  {--- When thinking is enabled, temperature is forced to 1.0 to satisfy
       the business/API constraint enforced by this project. The user setting
       is therefore used only when thinking is disabled. }
  if TStateChecking.HasTopP(AState) then
    Exit(False);

  if TStateChecking.ModelVersion47Check(AState) then
    Exit(False);

  if TStateChecking.HasThinking(AState) then
    begin
      if Assigned(ParamProc) then
        ParamProc(1.0);
      Exit(True);
    end;

  var CoreParams := AState.CoreParamsState;

  Result := CoreParams.Settings.Temperature.Enabled;
  if Result and Assigned(ParamProc) then
    ParamProc(CoreParams.Settings.Temperature.Value);
end;

class function TRequestSettingsBuilder.TryApplyTopK(const AState: TStateBuffer;
  const ParamProc: TProc<Double>): Boolean;
begin
  var CoreParams := AState.CoreParamsState;

  Result :=
    CoreParams.Sampling.TopK.Enabled and
    not TStateChecking.ModelVersion47Check(AState);

  if Result and Assigned(ParamProc) then
    ParamProc(CoreParams.Sampling.TopK.Value);
end;

class function TRequestSettingsBuilder.TryApplyTopP(const AState: TStateBuffer;
  const ParamProc: TProc<Double>): Boolean;
begin
  var CoreParams := AState.CoreParamsState;

  Result :=
    CoreParams.Sampling.TopP.Enabled and
    not TStateChecking.ModelVersion47Check(AState);

  if Result and Assigned(ParamProc) then
    ParamProc(CoreParams.Sampling.TopP.Value);
end;

class function TRequestSettingsBuilder.TryApplyStopSequences(
  const AState: TStateBuffer;
  const ParamProc: TProc): Boolean;
begin
  {--- Stop sequences are applied only when the option is enabled.
       The effective value is still read at the last moment by the caller so
       this method stays focused on the application condition only. }
  var CoreParams := AState.CoreParamsState;

  Result := CoreParams.Settings.StopString.Enabled;
  if Result and Assigned(ParamProc) then
    ParamProc();
end;

class procedure TRequestSettingsBuilder.Apply(
  const AState: TStateBuffer;
  const Params: TChatParams;
  const ADefaultMaxTokens: Integer);
begin
  {--- Central entry point that projects the UI/business state onto TChatParams.
       Each sub-builder encapsulates its own activation rule so this method
       remains readable orchestration rather than a block of conditions. }
  ApplyMaxTokens(AState,
    procedure(Value: Integer)
    begin
      Params.MaxTokens(Value);
    end,
    ADefaultMaxTokens);

  TryApplySystemPrompt(AState,
    procedure(Value: string)
    begin
      Params.System(Value);
    end);

  TryApplyTemperature(AState,
    procedure(Value: Double)
    begin
      Params.Temperature(Value);
    end);

  TryApplyStopSequences(AState,
    procedure
    begin
      {--- StopString is read intentionally at application time so it stays aligned
           with the effective configuration stored in CoreParamsState when the
           request is finally assembled. }
      var CoreParams := AState.CoreParamsState;
      Params.StopSequences(CoreParams.Settings.StopString.Value);
    end);

  TryApplyTopK(AState,
    procedure(Value: Double)
    begin
      Params.TopK(Value);
    end);

  TryApplyTopP(AState,
    procedure(Value: Double)
    begin
      Params.TopP(Value);
    end);
end;

{ TStateChecking }

class function TStateChecking.AdaptiveThinkingCheck(
  const AState: TStateBuffer): Boolean;
begin
  Result := ModelVersion46Check(AState) or ModelVersion47Check(AState);
end;

class function TStateChecking.HasEffort(const Effort: string): Boolean;
begin
  {--- The string "none" is used as the functional sentinel for disabling
       thinking mode. Any other value is treated as an active request for
       extended reasoning. }
  Result := not SameText(Effort, 'none');
end;

class function TStateChecking.HasFileToDownload(
  const AState: TStateBuffer): Boolean;
begin
  {--- Check if skills anthropic exists }
  var Skills := TParamsGetter.GetSkills(AState);

  Result := Length(Skills) > 0;
end;

class function TStateChecking.HasMCP(const AState: TStateBuffer): Boolean;
begin
  Result := Length(AState.Integration.Mcp) > 0;
end;

class function TStateChecking.HasSkills(const AState: TStateBuffer): Boolean;
begin
  Result := Length(AState.Integration.Skills) > 0;
end;

class function TStateChecking.ModelVersion46Check(
  const AState: TStateBuffer): Boolean;
begin
  var Model := AState.Model.ToLowerInvariant;
  Result := Model.Contains('-4-6');
end;

class function TStateChecking.ModelVersion47Check(
  const AState: TStateBuffer): Boolean;
begin
  var Model := AState.Model.ToLowerInvariant;
  Result := Model.Contains('-4-7');
end;

class function TStateChecking.SummarizedThinking(
  const AState: TStateBuffer): string;
begin
  Result := 'omitted';

  if Length(AState.Custom) = 0 then
    Exit;

  {--- Check the custom table to see if summarized is active. }
  for var Item in AState.Custom do
    if SameText(Item.Name.ToLowerInvariant, 'summarized') then
      Exit('summarized');
end;

class function TStateChecking.HasThinking(const AState: TStateBuffer): Boolean;
begin
  {--- Local helper used to centralize the "thinking enabled or not" rule.
       This information affects several request parameters, especially
       temperature, which becomes constrained when thinking is enabled. }
  Result := not SameText(AState.Thinking, 'none');
end;

class function TStateChecking.HasTopP(const AState: TStateBuffer): Boolean;
begin
  Result := AState.CoreParamsState.Sampling.TopP.Enabled;
end;

class function TStateChecking.MapToOutputEffort(const Effort: string;
  out BudgetCoef: Double): string;
begin
  {--- Maps the UI/business-level effort granularity to the values expected
       by output_config.effort. The mapping is not one-to-one:
       "medium" becomes "high" and "high" becomes "max". }
  if SameText(Effort, 'low') then
    begin
      BudgetCoef := 1.3;
      Exit('low');
    end;

  if SameText(Effort, 'medium') then
    begin
      BudgetCoef := 1.5;
      Exit('high');
    end;

  if SameText(Effort, 'high') then
    begin
      BudgetCoef := 1.7;
      Exit('max');
    end;

  {--- An empty return means no usable output_config can be produced.
       The calling code relies on this behavior to skip applying anything. }
  Result := '';
end;

{ TParamsGetter }

class function TParamsGetter.CheckFilename(const Filename,
  Folder: string): string;
begin
  var Candidate := TPath.GetFileName(Filename);
  var BaseName := TPath.GetFileNameWithoutExtension(Candidate);
  var Ext := TPath.GetExtension(Candidate);
  var index := 1;

  while Length(TDirectory.GetFiles(Folder, Candidate)) > 0 do
    begin
      Candidate := Format('%s (%d)%s', [BaseName, index, Ext]);
      Inc(index);
    end;

  Result := TPath.Combine(Folder, Candidate);
end;

class function TParamsGetter.GetMCPNames(
  const AState: TStateBuffer): TArray<string>;
begin
  SetLength(Result, Length(AState.Integration.Mcp));
  for var I := Low(AState.Integration.Mcp) to High(AState.Integration.Mcp) do
    Result[i] := AState.Integration.Mcp[I].Name;
end;

class function TParamsGetter.GetSkills(
  const AState: TStateBuffer): TArray<TSkillItem>;
begin
  SetLength(Result, Length(AState.Integration.Skills));

  var index := 0;
  for var Item In AState.Integration.Skills  do
    begin
      var isAnthropicSkills :=
        SameText(Item.Name, 'xlsx') or
        SameText(Item.Name, 'pptx') or
        SameText(Item.Name, 'pdf') or
        SameText(Item.Name, 'docx');

      if isAnthropicSkills then
        begin
          Result[index] := TSkillItem.Empty;
          Result[index].Id := Item.Name;
          Result[index].Name := Item.Name;
          Result[index].FileToDownload := True;
          Result[index].SkillType := 'anthropic';
          Result[index].Version := 'latest';
        end
      else
        begin
          Result[index] := TSkillItem.Empty;
          Result[index].Id := Item.Id;
          Result[index].Name := Item.Name;
          Result[index].FileToDownload := False;
          Result[index].SkillType := 'custom';
          Result[index].Version := 'latest';
        end;

      Inc(index);
    end;
end;

class function TParamsGetter.GetThinkingBudget(
  const AState: TStateBuffer; out MaxTokens: Integer): Integer;
var
  BudgetCoef: Double;
begin
  TStateChecking.MapToOutputEffort(AState.Thinking, BudgetCoef);

  MaxTokens := Trunc(AState.CoreParamsState.Settings.MaxToken.Value * BudgetCoef);

  Result := AState.CoreParamsState.Settings.MaxToken.Value;
end;

class function TParamsGetter.TryReadMCPCard(const Reader: TJsonReader;
  const X: string; out content, pat: string): Boolean;
begin
  content := '';
  pat := '';

  for var I := 0 to Reader.Count('cards') - 1 do
    begin
      var CardPath := 'cards[' + I.ToString + ']';

      if SameText(X, Reader.AsString(CardPath + '.id')) or
         SameText(X, Reader.AsString(CardPath + '.name')) then
        begin
          content := Reader.AsString(CardPath + '.content');
          pat := Reader.AsString(CardPath + '.pat');
          Exit(True);
        end;
    end;

  Result := False;
end;


{ TJSONArrayHelper }

class function TJSONArrayHelper.ArrayOfStringToJSonArrayAsString(
  const Value: TArray<string>): string;
begin
  Result := '';

  for var Item in Value do
    if Result.IsEmpty then
      Result := Item
    else
      Result := Result + ',' + Item;

  Result := Format('[%s]', [Result]);
end;

{ TArrayUtils }

class function TArrayUtils.Merge(const T1, T2: TArray<string>): TArray<string>;
begin
  Result := Copy(T1);
  var Count := Length(Result);

  for var Item2 in T2 do
    begin
      var Found := False;

      for var Item1 in T1 do
        if SameText(Item1, Item2) then
          begin
            Found := True;
            Break;
          end;

      if Found then
        Continue;

      SetLength(Result, Count + 1);
      Result[Count] := Item2;
      Inc(Count);
    end;
end;

{ TSkillItem }

class function TSkillItem.Empty: TSkillItem;
begin
  Result := Default(TSkillItem);
end;

{ TCustomSkill }

class function TCustomSkill.Empty: TCustomSkill;
begin
  Result := Default(TCustomSkill);
end;

{ TSkillHelper }

class function TSkillHelper.ExtractCustomSkills(
  const SkillsJsonAsString: string): TArray<TCustomSkill>;
begin
  SetLength(Result, 0);

  var Reader := TJsonReader.Parse(SkillsJsonAsString);
  if not Reader.IsValid then
    Exit;

  var Count := Reader.Count('cards');

  for var I := 0 to Count - 1 do
    begin
      var Path := Format('cards[%d]', [I]);

      if not SameText(Reader.AsString(Path + '.content'), 'custom') then
        Continue;

      var ID := Reader.AsString(Path + '.id');
      var Name := Reader.AsString(Path + '.name');

      if ID.IsEmpty or Name.IsEmpty then
        Continue;

      var SkillIndex := Length(Result);
      SetLength(Result, SkillIndex + 1);

      Result[SkillIndex].ID := ID;
      Result[SkillIndex].Name := Name;
    end;
end;

class function TSkillHelper.TryToUpdateID(const SkillJsonAsString, AName,
  NewId: string; const ParamProc: TProc<string>): Boolean;
var
  Writer: TJsonWriter;
begin
  Result := False;

  if AName.IsEmpty or NewId.IsEmpty then
    Exit;

  var Reader := TJsonReader.Parse(SkillJsonAsString);
  if not Reader.IsValid then
    Exit;

  var CardCount := Reader.Count('cards');

  for var I := 0 to CardCount - 1 do
    begin
      var CardPath := Format('cards[%d]', [I]);

      if not SameText(Reader.AsString(CardPath + '.content'), 'custom') then
        Continue;

      if not SameText(Reader.AsString(CardPath + '.name'), AName) then
        Continue;

      Writer := TJsonWriter.Parse(SkillJsonAsString);

      Result := Writer.SetString(CardPath + '.id', NewId);
      Break;
    end;

  if Result and Assigned(ParamProc) then
    ParamProc(Writer.Format());
end;

end.

unit Demo.Anthropic.Context;

interface

{$REGION 'TMessageParam'}
(*

  Conversation context for the pythia-anthropic VCL demo.

  This unit exposes an injectable IContext that lets TAnthropicServices
  (Demo.Anthropic.Services.pas) prepend the in-flight conversation history
  to the messages array assembled before each streamed request.

  History source
  --------------
  History is read from IPythiaBrowser.PersistentChat. Sessions and turns are
  managed by WVPythia.ChatSession.Controller.TPersistentChat: the active
  session is exposed through CurrentChat, and each TChatTurn holds the
  prompt/response pair persisted at the end of a previous round-trip, plus
  the raw streamed response in JsonResponse.

  Tour assembly
  -------------
  Each completed turn produces one user message followed by one assistant
  message, built through the TMessages helper (Anthropic.Helpers.pas). The
  current in-flight content blocks are appended last as the trailing user
  message. User-side replay stays on plain text; the prompt/files/images
  pipeline of the original request is not mirrored here.

  Assistant replay (rich blocks)
  ------------------------------
  As an example, the assistant message of each historical turn is
  reconstructed from TChatTurn.JsonResponse to carry back the following
  block types:

    - TRedactedThinkingBlockParam                  (reasoning)
    - TServerToolUseBlockParam                     (server-executed tool call)
    - TMCPToolUseBlockParam                        (MCP tool call)
    - TToolResultBlockParam                        (tool result echo)
    - TTextEditorCodeExecutionToolResultBlockParam (text-editor result echo)
    - TBashCodeExecutionToolResultBlockParam       (bash result echo)
    - TMCPToolResultBlockParam                     (MCP result echo)

  Note on tool_use / tool_result pairing
  --------------------------------------
  Anthropic's Messages API rejects any historical assistant turn that
  emits a server_tool_use block without echoing back its matching result
  block on replay, for example a text_editor_code_execution server
  tool_use must be followed by text_editor_code_execution_tool_result.
  Each newly supported server_tool_use kind therefore needs its result
  counterpart added to BuildAssistantContent, otherwise the next request
  fails with a 400:

    messages.N: <kind> tool use with id ... was found without a
    corresponding <kind>_tool_result block.

  Plain text blocks are also rebuilt from text_delta deltas so the visible
  assistant content is not lost in the process. Any other block type
  (regular tool_use, citations, container uploads, etc.) is intentionally
  skipped. This unit is a pedagogical sample, not an exhaustive replay.

  JsonResponse format
  -------------------
  TChatTurn.JsonResponse is a sequence of stream-event JSON objects
  separated by sLineBreak, exactly as accumulated by TEventData.Aggregate
  in Anthropic.Chat.StreamCallbacks. The two events that matter for
  reconstruction are:

    {"type":"content_block_start","index":N,"content_block":{...}}
    {"type":"content_block_delta","index":N,"delta":{...}}

  Each event is parsed with WVPythia.JSON.SafeReader.TJsonReader; per-block
  state is accumulated in a snapshot keyed by the block index, then emitted
  as the corresponding T<X>BlockParam (Anthropic.Chat.Request).

  Tool / MCP replay extension
  ---------------------------
  For richer tool-loop replay (interleaved tool_use / tool_result across
  turns) take inspiration from Anthropic.Context.Helper.TTurns; the
  building blocks (TPayload, TGenerationManager.Context.CreateToolUse,
  CreateToolResult) are the same.

  Beta flags aggregation
  ----------------------
  IContext.BetaExtract scans every TChatTurn.JsonPrompt of the current
  session, parses each one as JSON and collects the values found in the
  top-level "beta" array. The result is the deduplicated union of every
  beta that was activated on any prior turn, in order of first
  appearance, useful to keep the next request opted into the same
  feature flags (skills, code execution, etc.) that the conversation was
  bootstrapped with, without forcing the caller to track them
  separately.

  Container reuse (skills / code execution)
  -----------------------------------------
  When the user enabled a skill (xlsx, code execution, ...) on the first
  turn, the API returned a server-side container in the message_start
  event:

    {"type":"message_start","message":{"id":"...","container":{"id":"cont_..."}}}

  Subsequent turns must echo that container id back in their request
  payload (TChatParams.Container) so the same container,s and therefore
  the same loaded skills, working directory, and execution state, is
  reused instead of provisioned again. IContext.LastContainerId scans the
  history backwards and returns the most recent non-empty container.id
  found in any prior TChatTurn.JsonResponse. The service layer reads it
  before assembling the request and merges it into TContainerParams.Id
  alongside the skills selection of the current turn.

*)

{$ENDREGION}

uses
  System.SysUtils, System.Generics.Collections, System.JSON,
  WVPythia.JSON.SafeReader,
  Anthropic, Anthropic.Types, Anthropic.Helpers, Anthropic.API.JsonSafeReader,
  WVPythia.Chat.Interfaces, WVPythia.ChatSession.Controller, WVPythia.Vendors.Services;

type
  IContext = interface
    ['{9E1085A1-AA34-49CE-ADB7-A5E655D7D204}']
    function HasHistory: Boolean;

    function GetHistory: TArray<TMessageParam>;

    function LastContainerId: string;

    function BetaExtract: TArray<string>;

    function BuildMessages(
      const AState: TStateBuffer;
      const ACurrentContent: TArray<TContentBlockParam>): TArray<TMessageParam>;
  end;

  TBlockSnapshotKind = (
    bskUnknown,
    bskText,
    bskRedactedThinking,
    bskServerToolUse,
    bskMCPToolUse,
    bskToolResult,
    bskTextEditorCodeExecutionToolResult,
    bskBashCodeExecutionToolResult,
    bskMCPToolResult
  );

  TBlockSnapshot = record
    Index: Integer;
    Kind: TBlockSnapshotKind;
    BlockType: string;
    Id: string;
    Name: string;
    ServerName: string;
    Data: string;
    Text: string;
    InputJson: string;
    ToolUseId: string;
    Content: string;
    IsError: Boolean;
  end;

  TJsonResponseParser = record
  private
    class function MapKind(const ABlockType: string): TBlockSnapshotKind; static;

    class procedure HandleContentBlockStart(
      const AReader: TJsonReader;
      const ASnapshots: TDictionary<Integer, TBlockSnapshot>); static;

    class procedure HandleContentBlockDelta(
      const AReader: TJsonReader;
      const ASnapshots: TDictionary<Integer, TBlockSnapshot>); static;

    class procedure ProcessEvent(
      const AEventJson: string;
      const ASnapshots: TDictionary<Integer, TBlockSnapshot>); static;

    class function FlattenSorted(
      const ASnapshots: TDictionary<Integer, TBlockSnapshot>): TArray<TBlockSnapshot>; static;
  public
    class function Parse(const AJsonResponse: string): TArray<TBlockSnapshot>; static;
  end;

  TAnthropicContext = class(TInterfacedObject, IContext)
  private
    FBrowser: IPythiaBrowser;

    function CurrentSession: TChatSession;
    function HistoryTurns(const AChat: TChatSession): TArray<TChatTurn>;

    function ExtractContainerIdFromJsonResponse(
      const AJsonResponse: string): string;

    function BuildAssistantContent(
      const ATurn: TChatTurn): TArray<TContentBlockParam>;

    function BuildRedactedThinkingBlock(
      const ASnapshot: TBlockSnapshot): TContentBlockParam;

    function BuildServerToolUseBlock(
      const ASnapshot: TBlockSnapshot): TContentBlockParam;

    function BuildMCPToolUseBlock(
      const ASnapshot: TBlockSnapshot): TContentBlockParam;

    function BuildToolResultBlock(
      const ASnapshot: TBlockSnapshot): TContentBlockParam;

    function BuildTextEditorCodeExecutionToolResultBlock(
      const ASnapshot: TBlockSnapshot): TContentBlockParam;

    function BuildBashCodeExecutionToolResultBlock(
      const ASnapshot: TBlockSnapshot): TContentBlockParam;

    function BuildMCPToolResultBlock(
      const ASnapshot: TBlockSnapshot): TContentBlockParam;

    procedure AppendTurn(
      var AMessages: TMessages;
      const ATurn: TChatTurn);
  public
    constructor Create(const ABrowser: IPythiaBrowser);

    function HasHistory: Boolean;

    function GetHistory: TArray<TMessageParam>;

    function LastContainerId: string;

    function BetaExtract: TArray<string>;

    function BuildMessages(
      const AState: TStateBuffer;
      const ACurrentContent: TArray<TContentBlockParam>): TArray<TMessageParam>;

    class function CreateInstance(const ABrowser: IPythiaBrowser): IContext; static;
  end;

implementation

{ TJsonResponseParser }

class function TJsonResponseParser.MapKind(
  const ABlockType: string): TBlockSnapshotKind;
begin
  {--- Maps the wire-level block discriminator to the local enum. Any value
       outside the example scope falls back to bskUnknown so the emitter can
       silently skip it. }
  if SameText(ABlockType, 'text') then
    Exit(bskText);

  if SameText(ABlockType, 'redacted_thinking') then
    Exit(bskRedactedThinking);

  if SameText(ABlockType, 'server_tool_use') then
    Exit(bskServerToolUse);

  if SameText(ABlockType, 'mcp_tool_use') then
    Exit(bskMCPToolUse);

  if SameText(ABlockType, 'tool_result') then
    Exit(bskToolResult);

  if SameText(ABlockType, 'text_editor_code_execution_tool_result') then
    Exit(bskTextEditorCodeExecutionToolResult);

  if SameText(ABlockType, 'bash_code_execution_tool_result') then
    Exit(bskBashCodeExecutionToolResult);

  if SameText(ABlockType, 'mcp_tool_result') then
    Exit(bskMCPToolResult);

  Result := bskUnknown;
end;

class procedure TJsonResponseParser.HandleContentBlockStart(
  const AReader: TJsonReader;
  const ASnapshots: TDictionary<Integer, TBlockSnapshot>);
var
  Snapshot: TBlockSnapshot;
begin
  (*--- Seeds a snapshot from the immutable fields carried by the
        content_block_start event:

           {"type":"content_block_start","index":N,"content_block":{...}}

        Per-type relevant fields (id, name, server_name, data, tool_use_id,
        initial content/text, is_error) are eagerly read; missing values
        default to empty strings or False, which the emitter treats as
        absent.
  *)
  var Idx := AReader.AsInteger('index', -1);
  if Idx < 0 then
    Exit;

  Snapshot := Default(TBlockSnapshot);
  Snapshot.Index := Idx;
  Snapshot.BlockType := AReader.AsString('content_block.type');
  Snapshot.Kind := MapKind(Snapshot.BlockType);
  Snapshot.Id := AReader.AsString('content_block.id');
  Snapshot.Name := AReader.AsString('content_block.name');
  Snapshot.ServerName := AReader.AsString('content_block.server_name');
  Snapshot.Data := AReader.AsString('content_block.data');
  Snapshot.ToolUseId := AReader.AsString('content_block.tool_use_id');
  Snapshot.Content := AReader.AsString('content_block.content');
  Snapshot.IsError := AReader.AsBoolean('content_block.is_error', False);
  Snapshot.Text := AReader.AsString('content_block.text');

  ASnapshots.AddOrSetValue(Idx, Snapshot);
end;

class procedure TJsonResponseParser.HandleContentBlockDelta(
  const AReader: TJsonReader;
  const ASnapshots: TDictionary<Integer, TBlockSnapshot>);
var
  Snapshot: TBlockSnapshot;
begin
  (*--- Merges a content_block_delta event into the snapshot keyed by index:

           {"type":"content_block_delta","index":N,"delta":{"type":...}}

         Two delta types are aggregated here:
           - input_json_delta concatenates "partial_json" to rebuild the
             full input object of a tool_use / server_tool_use / mcp_tool_use
             block once content_block_stop has been seen.
           - text_delta concatenates "text" to rebuild the visible text of a
             text block.

         Other delta variants (thinking_delta, signature_delta, citations)
         fall outside the example scope and are deliberately ignored.
  *)

  var Idx := AReader.AsInteger('index', -1);
  if Idx < 0 then
    Exit;

  if not ASnapshots.TryGetValue(Idx, Snapshot) then
    Exit;

  var DeltaType := AReader.AsString('delta.type');

  if SameText(DeltaType, 'input_json_delta') then
    Snapshot.InputJson :=
      Snapshot.InputJson + AReader.AsString('delta.partial_json')
  else
  if SameText(DeltaType, 'text_delta') then
    Snapshot.Text :=
      Snapshot.Text + AReader.AsString('delta.text')
  else
    Exit;

  ASnapshots.AddOrSetValue(Idx, Snapshot);
end;

class procedure TJsonResponseParser.ProcessEvent(
  const AEventJson: string;
  const ASnapshots: TDictionary<Integer, TBlockSnapshot>);
begin
  {--- Single-event router: trims, parses with TJsonReader, and dispatches
       on the top-level "type" field. Malformed entries are silently
       skipped so a partially corrupted stream still produces useful
       output. }
  if AEventJson.Trim.IsEmpty then
    Exit;

  var Reader := TJsonReader.Parse(AEventJson);
  if not Reader.IsValid then
    Exit;

  var EventType := Reader.AsString('type');

  if SameText(EventType, 'content_block_start') then
    HandleContentBlockStart(Reader, ASnapshots)
  else
  if SameText(EventType, 'content_block_delta') then
    HandleContentBlockDelta(Reader, ASnapshots);
end;

class function TJsonResponseParser.FlattenSorted(
  const ASnapshots: TDictionary<Integer, TBlockSnapshot>): TArray<TBlockSnapshot>;
begin
  {--- TDictionary does not guarantee enumeration order. Flattening through
       a sorted index list keeps the emitted blocks in the same sequence as
       in the original streamed response. }
  Result := [];

  var Indices := TList<Integer>.Create;
  try
    for var Key in ASnapshots.Keys do
      Indices.Add(Key);

    Indices.Sort;

    for var Key in Indices do
      Result := Result + [ASnapshots[Key]];
  finally
    Indices.Free;
  end;
end;

class function TJsonResponseParser.Parse(
  const AJsonResponse: string): TArray<TBlockSnapshot>;
begin
  {--- Splits the persisted JsonResponse on sLineBreak (TEventData.Aggregate
       always inserts that separator before each chunk) and processes each
       event individually. Empty lines, including the leading separator
       are filtered out. }
  Result := [];
  if AJsonResponse.Trim.IsEmpty then
    Exit;

  var Snapshots := TDictionary<Integer, TBlockSnapshot>.Create;
  try
    {--- Empty entries (the leading sLineBreak inserted by TEventData.Aggregate
         before the very first event, blank trailing tokens) are skipped by
         ProcessEvent itself, so a plain Split without options is enough. }
    for var Event in AJsonResponse.Split([sLineBreak]) do
      ProcessEvent(Event, Snapshots);

    Result := FlattenSorted(Snapshots);
  finally
    Snapshots.Free;
  end;
end;

{ TAnthropicContext }

constructor TAnthropicContext.Create(const ABrowser: IPythiaBrowser);
begin
  inherited Create;
  FBrowser := ABrowser;
end;

class function TAnthropicContext.CreateInstance(
  const ABrowser: IPythiaBrowser): IContext;
begin
  Result := TAnthropicContext.Create(ABrowser);
end;

function TAnthropicContext.CurrentSession: TChatSession;
begin
  {--- Resolves the active TChatSession through the browser-facing
       IPersistentChat. A nil chain is tolerated: it simply yields an empty
       history downstream. }
  Result := nil;
  if not Assigned(FBrowser) then
    Exit;

  var Persistent := FBrowser.PersistentChat;
  if not Assigned(Persistent) then
    Exit;

  Result := Persistent.CurrentChat;
end;

function TAnthropicContext.HistoryTurns(
  const AChat: TChatSession): TArray<TChatTurn>;
begin
  {--- Selects the turns that already carry both a prompt and a response.

       The very last entry of TChatSession.Data is the in-flight prompt
       allocated by TPersistentChat.AddPrompt right before streaming starts;
       its Response is still empty at request build time, so it is excluded
       from history replay. }
  Result := [];
  if not Assigned(AChat) then
    Exit;

  var Turns := AChat.Data;
  var TurnHigh := High(Turns);
  if TurnHigh < 0 then
    Exit;

  for var I := 0 to TurnHigh - 1 do
    begin
      var Turn := Turns[I];
      if not Assigned(Turn) then
        Continue;

      if Turn.Prompt.Trim.IsEmpty or Turn.Response.Trim.IsEmpty then
        Continue;

      Result := Result + [Turn];
    end;
end;

function TAnthropicContext.BuildRedactedThinkingBlock(
  const ASnapshot: TBlockSnapshot): TContentBlockParam;
begin
  {--- Redacted thinking carries opaque server-side reasoning bytes through
       the "data" field. Replaying it tells the API the prior turn already
       produced redacted reasoning so it can be linked into the next round. }
  Result := TRedactedThinkingBlockParam.New
    .Data(ASnapshot.Data);
end;

function TAnthropicContext.BuildServerToolUseBlock(
  const ASnapshot: TBlockSnapshot): TContentBlockParam;
begin
  (*--- Only synthesize an empty JSON object when no input was captured at all.
        A non-empty but invalid buffer is deliberately not coerced to "{}",
        because that would change the semantics of the replayed tool call.
  *)
  var Block := TServerToolUseBlockParam.New
    .Id(ASnapshot.Id)
    .Name(ASnapshot.Name);

  var InputJson := ASnapshot.InputJson;
  if InputJson.Trim.IsEmpty then
    InputJson := '{}';

  if TJsonCheck.IsValid(InputJson) then
    Block := Block.Input(InputJson);

  Result := Block;
end;

function TAnthropicContext.BuildMCPToolUseBlock(
  const ASnapshot: TBlockSnapshot): TContentBlockParam;
begin
  {--- MCP tool use mirrors server_tool_use but adds the originating MCP
       server name. The same defensive Input handling applies. }
  var Block := TMCPToolUseBlockParam.New
    .Id(ASnapshot.Id)
    .Name(ASnapshot.Name)
    .ServerName(ASnapshot.ServerName);

  var InputJson := ASnapshot.InputJson;
  if InputJson.Trim.IsEmpty then
    InputJson := '{}';

  if TJsonCheck.IsValid(InputJson) then
    Block := Block.Input(InputJson);

  Result := Block;
end;

function TAnthropicContext.BuildToolResultBlock(
  const ASnapshot: TBlockSnapshot): TContentBlockParam;
begin
  {--- Tool result echo: only the textual "content" form is replayed here.
       Structured array content (TArray<TContentBlockParam>) would require
       a recursive parse and is left out of this example. }
  var Block := TToolResultBlockParam.New
    .ToolUseId(ASnapshot.ToolUseId)
    .Content(ASnapshot.Content);

  if ASnapshot.IsError then
    Block := Block.IsError(True);

  Result := Block;
end;

function TAnthropicContext.BuildTextEditorCodeExecutionToolResultBlock(
  const ASnapshot: TBlockSnapshot): TContentBlockParam;
begin
  (*--- Server-executed text-editor result. The Messages API rejects any
        prior assistant turn that emitted a text_editor_code_execution
        server_tool_use without echoing back its matching
        text_editor_code_execution_tool_result block on replay � the
        request would fail with:

          messages.N: text_editor_code_execution tool use with id ...
          was found without a corresponding
          text_editor_code_execution_tool_result block.

        The result inner shape is polymorphic (view / create / str_replace
        / error) and the SDK exposes typed Content() overloads only. To
        keep the example concise we capture the raw content_block.content
        JSON when the block_start arrives (already stored as
        ASnapshot.Content thanks to TJsonReader.GetPathString falling back
        to ToJSON for object nodes), parse it back into a TJSONValue and
        inject it directly through the inherited TJSONParam.Add('content',
        ...) entry point. This preserves whatever inner type the server
        produced without requiring a per-variant builder here.
  *)
  var Block := TTextEditorCodeExecutionToolResultBlockParam.New
    .ToolUseId(ASnapshot.ToolUseId);

  if not ASnapshot.Content.Trim.IsEmpty then
    begin
      var Inner := TJSONObject.ParseJSONValue(ASnapshot.Content);
      if Assigned(Inner) then
        Block.Add('content', Inner);
    end;

  Result := Block;
end;

function TAnthropicContext.BuildBashCodeExecutionToolResultBlock(
  const ASnapshot: TBlockSnapshot): TContentBlockParam;
begin
  (*--- Server-executed bash result. Same pairing constraint as the
        text-editor variant: omitting it on replay triggers a 400 with

          messages.N: bash_code_execution tool use with id ... was found
          without a corresponding bash_code_execution_tool_result block.

        TBashCodeExecutionToolResultBlockParam exposes only typed Content()
        overloads (TBashCodeExecutionResultBlockParam and the matching
        error variant), so we follow the same shortcut as the text-editor
        builder: capture the raw content_block.content JSON in
        ASnapshot.Content and inject it through the inherited
        TJSONParam.Add('content', ...) entry point. The server's original
        inner shape is preserved verbatim, which is all the API requires
        to acknowledge the prior tool_use.
  *)
  var Block := TBashCodeExecutionToolResultBlockParam.New
    .ToolUseId(ASnapshot.ToolUseId);

  if not ASnapshot.Content.Trim.IsEmpty then
    begin
      var Inner := TJSONObject.ParseJSONValue(ASnapshot.Content);
      if Assigned(Inner) then
        Block.Add('content', Inner);
    end;

  Result := Block;
end;

function TAnthropicContext.BuildMCPToolResultBlock(
  const ASnapshot: TBlockSnapshot): TContentBlockParam;
begin
  (*--- MCP tool result. Pairs with a previously emitted mcp_tool_use:

          messages.N: mcp_tool_use with id ... was found without a
          corresponding mcp_tool_result block.

        TMCPToolResultBlockParam exposes both Content(string) and
        Content(TArray<TTextBlockParam>) overloads, but the wire shape
        coming back from the server can also be a heterogeneous JSON
        array of typed text/image content. To preserve that shape
        verbatim we try to parse the captured raw content first:

          - object / array  -> injected through Add('content', JSONValue)
                               so the original structure is replayed.
          - anything else   -> falls back to Content(string) and the leftover
                               TJSONValue (e.g. a bare TJSONString) is freed.

        is_error is a top-level field on the mcp_tool_result block (unlike
        the text-editor / bash variants where the error is conveyed via a
        dedicated inner type), so it is forwarded through IsError() when
        set on the snapshot.
  *)
  var Block := TMCPToolResultBlockParam.New
    .ToolUseId(ASnapshot.ToolUseId);

  if not ASnapshot.Content.Trim.IsEmpty then
    begin
      var Inner := TJSONObject.ParseJSONValue(ASnapshot.Content);
      if Assigned(Inner) and ((Inner is TJSONObject) or (Inner is TJSONArray)) then
        Block.Add('content', Inner)
      else
        begin
          if Assigned(Inner) then
            Inner.Free;
          Block.Content(ASnapshot.Content);
        end;
    end;

  if ASnapshot.IsError then
    Block.IsError(True);

  Result := Block;
end;

function TAnthropicContext.BuildAssistantContent(
  const ATurn: TChatTurn): TArray<TContentBlockParam>;
begin
  {--- Walks the parsed snapshots in original index order and emits the
       block subset covered by this example. Order matters because the
       Messages API expects reasoning blocks before content and tool_use
       before any subsequent tool_result. }
  Result := [];

  for var S in TJsonResponseParser.Parse(ATurn.JsonResponse) do
    case S.Kind of
      bskText:
        if not S.Text.Trim.IsEmpty then
          Result := Result + [TTextBlockParam.New.Text(S.Text)];

      bskRedactedThinking:
        if not S.Data.IsEmpty then
          Result := Result + [BuildRedactedThinkingBlock(S)];

      bskServerToolUse:
        Result := Result + [BuildServerToolUseBlock(S)];

      bskMCPToolUse:
        Result := Result + [BuildMCPToolUseBlock(S)];

      bskToolResult:
        Result := Result + [BuildToolResultBlock(S)];

      bskTextEditorCodeExecutionToolResult:
        Result := Result + [BuildTextEditorCodeExecutionToolResultBlock(S)];

      bskBashCodeExecutionToolResult:
        Result := Result + [BuildBashCodeExecutionToolResultBlock(S)];

      bskMCPToolResult:
        Result := Result + [BuildMCPToolResultBlock(S)];
    end;
end;

procedure TAnthropicContext.AppendTurn(
  var AMessages: TMessages;
  const ATurn: TChatTurn);
begin
  {--- One past round-trip = one user message + one assistant message.

       The user side is replayed as plain text (the original prompt
       attachments are not mirrored here). The assistant side is rebuilt
       from the streamed JsonResponse when possible, and falls back to
       the aggregated Response text otherwise: for example when the JSON
       buffer is empty or fully redacted. }
  AMessages := AMessages.User(ATurn.Prompt);

  var Content := BuildAssistantContent(ATurn);
  if Length(Content) = 0 then
    AMessages := AMessages.Assistant(ATurn.Response)
  else
    AMessages := AMessages.Assistant(Content);
end;

function TAnthropicContext.HasHistory: Boolean;
begin
  Result := Length(HistoryTurns(CurrentSession)) > 0;
end;

function TAnthropicContext.GetHistory: TArray<TMessageParam>;
begin
  var Messages := Generation.MessageParts;

  for var Turn in HistoryTurns(CurrentSession) do
    AppendTurn(Messages, Turn);

  Result := Messages;
end;

function TAnthropicContext.ExtractContainerIdFromJsonResponse(
  const AJsonResponse: string): string;
begin
  (*--- Walks the persisted stream and returns the last container.id seen
        in any message_start event:

          {"type":"message_start","message":{...,"container":{"id":"cont_..."}}}

        The id is normally identical across all message_start events of a
        single turn, but later events take precedence on principle so any
        late re-provisioning recorded in the buffer wins. An empty result
        means the prior turn did not allocate a container (no skills /
        code-execution was requested or the model returned no container
        block).
  *)
  Result := '';
  if AJsonResponse.Trim.IsEmpty then
    Exit;

  for var Event in AJsonResponse.Split([sLineBreak]) do
    begin
      if Event.Trim.IsEmpty then
        Continue;

      var Reader := TJsonReader.Parse(Event);
      if not Reader.IsValid then
        Continue;

      if not SameText(Reader.AsString('type'), 'message_start') then
        Continue;

      var Id := Reader.AsString('message.container.id');
      if not Id.IsEmpty then
        Result := Id;
    end;
end;

function TAnthropicContext.LastContainerId: string;
begin
  (*--- Scans completed turns from the most recent backwards and returns
        the first non-empty container.id encountered. The traversal stops
        as soon as one is found so an older turn never overrides a fresher
        provisioning. Empty when no historical turn ever allocated a
        container, the caller then provisions a fresh one without an
        explicit "id" field, exactly as on the first turn.
  *)
  Result := '';

  var Turns := HistoryTurns(CurrentSession);
  for var I := High(Turns) downto Low(Turns) do
    begin
      var Id := ExtractContainerIdFromJsonResponse(Turns[I].JsonResponse);
      if not Id.IsEmpty then
        Exit(Id);
    end;
end;

function TAnthropicContext.BetaExtract: TArray<string>;
const
  BETA_PATH = 'beta';
begin
  (*--- Aggregates the unique beta flags requested across every previously
        sent turn of the current session.

        TChatTurn.JsonPrompt holds the formatted JSON of the request that
        was actually sent to the API (assigned by the orchestrator from
        TManagedItemLLMResult.PromptJson on completion), so its top-level
        "beta" array (when present) reflects the betas that the model
        was opted into for that turn:

            "beta": [
              "code-execution-2025-08-25",
              "skills-2025-10-02"
            ]

        Turns whose JsonPrompt is still empty (the in-flight turn before
        its first round-trip completed) are naturally skipped. Order of
        first appearance is preserved in the result; subsequent
        occurrences of an already-seen value are dropped through a small
        seen-set so the final list contains no duplicates. Turns that do
        not carry a "beta" array (the regular case when no feature flag
        is in use) contribute nothing and are silently bypassed by the
        IsArrayNode guard.
  *)
  Result := [];

  var Chat := CurrentSession;
  if not Assigned(Chat) then
    Exit;

  var Seen := TDictionary<string, Boolean>.Create;
  try
    for var Turn in Chat.Data do
      begin
        if not Assigned(Turn) then
          Continue;

        if Turn.JsonPrompt.Trim.IsEmpty then
          Continue;

        var Reader := TJsonReader.Parse(Turn.JsonPrompt);
        if not Reader.IsValid then
          Continue;

        if not Reader.IsArrayNode(BETA_PATH) then
          Continue;

        var Total := Reader.Count(BETA_PATH);
        for var I := 0 to Total - 1 do
          begin
            var Beta := Reader.AsString(Format('%s[%d]', [BETA_PATH, I]));
            if Beta.Trim.IsEmpty then
              Continue;

            if Seen.ContainsKey(Beta) then
              Continue;

            Seen.Add(Beta, True);
            Result := Result + [Beta];
          end;
      end;
  finally
    Seen.Free;
  end;
end;

function TAnthropicContext.BuildMessages(
  const AState: TStateBuffer;
  const ACurrentContent: TArray<TContentBlockParam>): TArray<TMessageParam>;
begin
  {--- Assembles the full timeline:
         history turns first, current user content blocks last.

       AState is accepted to keep the door open for context-window aware
       trimming (model max tokens, summarization, etc.) without changing the
       call site in TAnthropicServices. }
  var Messages := Generation.MessageParts;

  for var Turn in HistoryTurns(CurrentSession) do
    AppendTurn(Messages, Turn);

  Messages := Messages.User(ACurrentContent);

  Result := Messages;
end;

end.

unit Demo.Anthropic.AsyncUtils;

interface

uses
  System.SysUtils, System.IOUtils, System.Classes, System.Threading, System.JSON,
  Anthropic, Anthropic.Types, Anthropic.Helpers,
  WVPythia.Chat.Interfaces, WVPythia.Vendors.Services, WVPythia.TextFile.Helper,
  WVPythia.JSON.SafeWriter,
  Demo.Anthropic.Helpers;

type
  IAnthropicClientUtils = interface
    ['{7A5E70A4-251C-47B0-BBBA-185DA65A2A76}']
    procedure AsyncFetchFile(const ID: string; const Filename: string);
    procedure ASyncSessionRename(const ChatID: string; const ContentToSummarize: string);
    procedure CustomSkillRegister(const SkillID: string; const Folder: string);
  end;

  TAnthropicClientUtils = class(TInterfacedObject, IAnthropicClientUtils)
  private
    FClient: IAnthropic;
    FPythia: IPythiaBrowser;
  protected
    procedure SkillRegister(const SkillID: string; const AName: string);
  public
    constructor Create(const AClient: IAnthropic; const ABrowser: IPythiaBrowser);

    procedure AsyncFetchFile(const ID: string; const Filename: string);
    procedure ASyncSessionRename(const ChatID: string; const ContentToSummarize: string);
    procedure CustomSkillRegister(const SkillID: string; const AName: string);
  end;

implementation

var
  GSkillCardsJsonLock: TObject;

function TryUpdateSkillIDInSkillCardsFile(
  const SkillCardsFileName: string;
  const AName: string;
  const NewId: string): Boolean;
begin
  Result := False;
  var UpdatedSkillJsonAsString := '';

  if SkillCardsFileName.IsEmpty then
    Exit;

  TMonitor.Enter(GSkillCardsJsonLock);
  try
    if not FileExists(SkillCardsFileName) then
      Exit;

    var SkillJsonAsString := TFileIOHelper.LoadFromFile(SkillCardsFileName);

    Result := TSkillHelper.TryToUpdateID(
      SkillJsonAsString,
      AName,
      NewId,
      procedure (NewSkillsJsonAsString: string)
      begin
        UpdatedSkillJsonAsString := NewSkillsJsonAsString;
      end);

    if Result then
      TFileIOHelper.SaveToFile(SkillCardsFileName, UpdatedSkillJsonAsString);

  finally
    TMonitor.Exit(GSkillCardsJsonLock);
  end;
end;

{ TAnthropicClientUtils }

procedure TAnthropicClientUtils.AsyncFetchFile(const ID, Filename: string);
begin
  var Promise := FClient.Files.AsyncAwaitDownload(ID);

  Promise
    .&Then(
      procedure (Value: TFileDownloaded)
      begin
        Value.SaveToFile(FileName);
      end)
    .&Catch(
      procedure (E: Exception)
      begin
        if Assigned(FPythia) then
          FPythia.DisplayError(Format('File not found:#10%s', [Filename]))
      end);
end;

procedure TAnthropicClientUtils.ASyncSessionRename(const ChatID,
  ContentToSummarize: string);
begin
  var Model := 'claude-haiku-4-5';
  var MaxTokens := 1000;
  var SystemPrompt :=
    '# Rules :' + slineBreak +
    '- Do not comment on your answer' + slineBreak +
    '- Display only the answer' + slineBreak +
    '- Do not use articles or pronouns' + slineBreak +
    '- Write at most 7 words';
  var Prompt := Format('Summarize the following message:'#10'%s', [ContentToSummarize]);

  var Payload: TChatParamProc :=
    procedure (Params: TChatParams)
    begin
      Params
        .Model(Model)
        .System(SystemPrompt)
        .Messages( Generation.MessageParts
          .User(Prompt)
        )
        .MaxTokens(MaxTokens);
    end;

  var Promise := FClient.Chat.AsyncAwaitCreate(Payload);

  Promise
    .&Then(
      procedure (Value: TChat)
      begin
        var Name := '';

        for var Content in Value.Content do
          begin
            if Content.&Type = TContentBlockType.text then
              Name := Content.Text;
          end;

        if Name.IsEmpty then
          Exit;

        if not Assigned(FPythia)  then
          Exit;

        if not Assigned(FPythia.PersistentChat) then
          Exit;

        FPythia.PersistentChat.UpdateChatTitleById(ChatID, Name);
        FPythia.ChatSessionRename(ChatID, Name);
      end)
    .&Catch(
      procedure (E: Exception)
      begin
        {--- Silent error }
      end);
end;

constructor TAnthropicClientUtils.Create(const AClient: IAnthropic;
  const ABrowser: IPythiaBrowser);
begin
  inherited Create;
  FClient := AClient;
  FPythia := ABrowser;
end;

procedure TAnthropicClientUtils.CustomSkillRegister(
  const SkillID,
  AName: string);
begin
  var Promise := FClient.Skills.AsyncAwaitRetrieve(SkillID);

  Promise
    .&Then(
      procedure (Value: TSkill)
      begin
        FPythia.DisplaySuccess(Format('Custom skill registred: %s', [Value.Id]));
      end)
    .&Catch(
      procedure (E: Exception)
      begin
        if E.Message.StartsWith('error (404)') then
          SkillRegister(SkillID, AName);
      end);
end;

procedure TAnthropicClientUtils.SkillRegister(const SkillID, AName: string);
begin
  if not Assigned(FPythia) then
    Exit;

  var Folder := TPath.Combine(FPythia.GetAppRawName, AName);
  var SkillCardsFileName := FPythia.GetSkillCardsFileName;
  if not FileExists(SkillCardsFileName) then
    Exit;

  var Payload: TSkillFormDataParamProc :=
    procedure (Params: TSkillFormDataParams)
    begin
      Params
        .DisplayTitle(AName)
        .Files(Folder);
    end;

  var Promise := FClient.Skills.AsyncAwaitCreate(Payload);

  Promise
    .&Then(
      procedure (Value: TSkill)
      begin
        TryUpdateSkillIDInSkillCardsFile(
          SkillCardsFileName,
          AName,
          Value.Id);
      end)
    .&Catch(
      procedure (E: Exception)
      begin
        if E.Message.StartsWith('error (400)') then
          begin
            TryUpdateSkillIDInSkillCardsFile(
              SkillCardsFileName,
              AName,
              '-1');
          end;
      end);
end;

initialization
  GSkillCardsJsonLock := TObject.Create;

finalization
  GSkillCardsJsonLock.Free;
end.

